  });
});

document.querySelectorAll("button").forEach((b) => {
  b.addEventListener("mouseleave", () => {
    console.log(b.textContent);
  });
});

// removeEventListener wymaga DOKLADNIE tej samej referencji funkcji,
// jaka zostala przekazana do addEventListener. Kazda arrow function
// zdefiniowana 'w miejscu' (np. () => console.log('klik')) tworzy NOWY,
// UNIKALNY obiekt funkcji w pamieci - nawet jesli DWIE takie funkcje maja
// identyczna tresc, sa to DWIE ROZNE referencje. Dlatego, aby moc pozniej
// usunac handler, MUSI on byc zapisany jako NAZWANA funkcja przypisana
// do zmiennej, uzywana identycznie w obu wywolaniach
// (addEventListener i removeEventListener).

document.getElementById("btn-double").addEventListener("dblclick", () => {
  console.log("Podwojne klikniecie!");
});

document.getElementById("btn-right").addEventListener(
  "click",
  () => console.log("raz"),
  { once: true, capture: false }
);

function pokazTyp(e) {
  console.log(e.type);
}

const btn = document.getElementById("btn-single");
btn.addEventListener("click", pokazTyp);
btn.removeEventListener("click", pokazTyp);
console.log(typeof pokazTyp); // "function" - referencja nadal istnieje

function pokaz() {
  console.log("klik");
}

const btn = document.getElementById("btn-double");
btn.addEventListener("click", pokaz);
btn.addEventListener("click", pokaz);
// mimo dwoch wywolan addEventListener, "pokaz" zostanie wywolane
// TYLKO RAZ na klikniecie - identyczna rejestracja (ten sam typ,
// ta sama referencja funkcji, te same opcje) jest ignorowana.

const wynik = document.getElementById("btn-single").addEventListener("click", () => {});
console.log(wynik); // undefined - addEventListener nie zwraca niczego uzytecznego,
// nie da sie go "lancuchowac" jak np. metod tablicowych zwracajacych this/nowa tablice.

const typy = ["mouseenter", "mouseleave", "click"];
const btn = document.getElementById("btn-single");

typy.forEach((typ) => {
  btn.addEventListener(typ, () => console.log(typ));
});

function niedodany() {}

document.getElementById("btn-right").removeEventListener("click", niedodany);
console.log("brak bledu - removeEventListener na nieistniejacym handlerze po prostu nic nie robi");

const btn = document.getElementById("btn-double");

btn.addEventListener("click", function () {
  console.log(this === btn); // true - w zwyklej funkcji this to element
});
// (w funkcji strzalkowej this bylby leksykalny, NIE element - rozdzial 7)

function handler(e, dodatkowy) {
  console.log(dodatkowy);
}

document.getElementById("btn-single").addEventListener("click", handler);
// Prawdziwe wywolanie przez przegladarke przekaze TYLKO obiekt zdarzenia -
// "dodatkowy" bedzie undefined. addEventListener, w odroznieniu od setTimeout,
// nie przyjmuje dodatkowych argumentow do przekazania handlerowi.

function stworzLicznikKlikniec() {
  return {
    n: 0,
    handler(e) {
      this.n++;
    }
  };
}

const licznik = stworzLicznikKlikniec();
document.getElementById("btn-double").addEventListener(
  "click",
  licznik.handler.bind(licznik)
);

document.getElementById("btn-right").addEventListener(
  "click",
  () => console.log("klik"),
  { passive: true }
);
// passive: true to obietnica dla przegladarki, ze handler NIGDY nie
// wywola e.preventDefault() - dzieki temu przegladarka moze od razu
// wykonac domyslna akcje (np. przewijanie), bez czekania na handler.

const btn = document.getElementById("btn-single");

function wypiszRaz(e) {
  console.log("raz");
  btn.removeEventListener("click", wypiszRaz);
}

btn.addEventListener("click", wypiszRaz);
// po pierwszym kliknieciu handler usuwa sam siebie - kolejne klikniecia nic nie robia

const btn = document.getElementById("btn-double");

btn.addEventListener("click", () => console.log("raz-tylko"), { once: true });
btn.addEventListener("click", () => console.log("zawsze"));
// pierwsze klikniecie: "raz-tylko" i "zawsze"
// drugie klikniecie: TYLKO "zawsze" - pierwszy handler byl jednorazowy

const komponent = {
  nazwa: "Panel",
  zainicjuj() {
    document.getElementById("btn-single").addEventListener("click", () => {
      console.log(this.nazwa);
    });
  }
};

komponent.zainicjuj();
// Arrow function NIE ma wlasnego this - uzywa this z metody zainicjuj(),
// czyli komponent. Zwykla funkcja dostalaby tu this = element #btn-single.

document.addEventListener("keydown", (e) => console.log(e.type));
document.addEventListener("keyup", (e) => console.log(e.type));
// document dziedziczy po EventTarget, dokladnie jak kazdy element HTML -
// mozna wiec uzywac na nim addEventListener do obslugi zdarzen globalnych
// (np. skrotow klawiszowych dzialajacych na calej stronie).

function podepnijZLimitem(element, typ, handler, limit) {
  let ile = 0;
  function wrapper(e) {
    ile++;
    handler(e);
    if (ile >= limit) {
      element.removeEventListener(typ, wrapper);
    }
  }
  element.addEventListener(typ, wrapper);
}

podepnijZLimitem(
  document.getElementById("btn-double"),
  "click",
  () => console.log("klik"),
  2
);
// po dwoch kliknieciach handler przestaje dzialac

document.getElementById("btn-right").addEventListener(
  "click",
  (e) => console.log(e.type),
  false
);
// Starszy zapis: trzeci argument jako boolean oznacza WYLACZNIE useCapture
// (false = faza bubbling, domyslna). Nowszy, elastyczniejszy zapis to obiekt
// { capture, once, passive } - pozwala ustawic wiecej niz jedna opcje naraz.

const przyciskiIds = ["btn-single", "btn-double", "btn-right"];
const przyciski = przyciskiIds.map((id) => document.getElementById(id));

przyciski.forEach((btn) => {
  btn.addEventListener("click", () => console.log(btn.id, "klikniety"));
});

const btn = document.getElementById("btn-single");
btn.addEventListener("click", () => console.log("oryginal"));

const klon = btn.cloneNode(true);
// klon NIE ma podpietego listenera - cloneNode kopiuje wylacznie
// strukture HTML (tagi, atrybuty, tresc), a nie listenery dodane
// przez addEventListener w JavaScript. Trzeba by je podpiac osobno.
console.log("listener trzeba dodac ponownie na klonie");

function raz(fn) {
  let wykonano = false;
  return function (...args) {
    if (wykonano) return;
    wykonano = true;
    fn(...args);
  };
}

document.getElementById("btn-double").addEventListener(
  "click",
  raz((e) => console.log("tylko raz, recznie"))
);

document.getElementById("btn-single").addEventListener("click", (e) => {
  console.log(typeof e.timeStamp, e.isTrusted);
});
// isTrusted jest true TYLKO dla zdarzen wywolanych realna akcja
// uzytkownika (np. faktyczne klikniecie mysza) - zdarzenie wywolane
// programowo przez element.dispatchEvent(new Event("click")) ma isTrusted === false.

function pokazTyp2(e) {
  console.log(e.type.toUpperCase().length);
}

document.addEventListener("keydown", pokazTyp2);

